impl Ticket for BlobTicket {
    const KIND: &'static str = "blob";

    fn encode_bytes(&self) -> Vec<u8> {
        let data = TicketWireFormat::Variant0(Variant0BlobTicket {
            node: Variant0NodeAddr {
                endpoint_id: self.addr.id,
                info: Variant0AddrInfo {
                    relay_url: self.addr.relay_urls().next().cloned(),
                    direct_addresses: self.addr.ip_addrs().cloned().collect(),
                },
            },
            format: self.format,
            hash: self.hash,
        });
        postcard::to_stdvec(&data).expect("postcard serialization failed")
    }

    fn decode_bytes(bytes: &[u8]) -> std::result::Result<Self, ParseError>

pub trait Ticket: Sized {
    const KIND: &'static str;
    fn encode_bytes(&self) -> Vec<u8>;
    fn decode_bytes(bytes: &[u8]) -> Result<Self, ParseError>;

    fn encode_string(&self) -> String {
        let mut out = Self::KIND.to_string();
        data_encoding::BASE32_NOPAD.encode_append(&self.encode_bytes(), &mut out);
        out.make_ascii_lowercase();
        out
    }

    fn decode_string(s: &str) -> Result<Self, ParseError> {
        let expected = Self::KIND;
        let Some(rest) = s.strip_prefix(expected) else {
            return Err(e!(ParseError::Kind { expected }));
        };
        let bytes = data_encoding::BASE32_NOPAD.decode(rest.to_ascii_uppercase().as_bytes())?;
        Self::decode_bytes(&bytes)
    }
}

